//go:build ignore

package main

import (
	"encoding/json"
	"log"
	"os"
	"path/filepath"
)

// Minimal maelstrom wrapper for this specific use case.
// In reality, we'll need to either:
// 1. Use the actual library which may not be fully loaded
// 2. Implement the basic JSON framing ourselves
//
// Let me check if we can build without importing the library first.

func main() {
	// Start the maelstrom node - we'll implement basic JSON message handling
	startNode()
}

func startNode() {
	for {
		line, err := os.ReadFile("/dev/stdin", 0)
		if err != nil {
			log.Println("Read error:", err)
			return
		}

		var msg map[string]interface{}
		if len(line) == 0 || line[0] == ' ' {
			continue
		}

		err = json.Unmarshal(line, &msg)
		if err != nil {
			log.Println("JSON parse error:", err)
			continue
		}

		msgType := msg["type"].(string)

		switch msgType {
		case "init":
			handleInit(msg)
		case "topology":
			handleTopology(msg)
		case "broadcast":
			handleBroadcast(msg)
		case "read":
			handleRead(msg)
		case "reply_to_me":
			// Handle incoming replies
			handleReplyToMe(msg)
		default:
			log.Printf("Unknown type: %s", msgType)
		}
	}
}

func handleInit(msg map[string]interface{}) {
	id := msg["id"].(string)
	log.Printf("Node %s initialized", id)

	// Parse topology
	body := msg["body"].(map[string]interface{})
	topologyMap, ok := body["topology"].(map[string]interface{})
	if !ok || len(topologyMap) == 0 {
		return
	}

	neighbors := make(map[string][]string)
	for nodeID, nList := range topologyMap {
		nListArr := nList.([]interface{})
		var strs []string
		for _, v := range nListArr {
			strs = append(strs, v.(string))
		}
		neighbors[nodeID] = strs
	}

	log.Printf("Node %s has neighbors: %+v", id, neighbors[id])

	// Store topology
	topologyCh, _ := getTopologyCh(id)
	topologyCh <- map[string][]string{
		id: neighbors[id],
	}

	if replyToMe, ok := msg["reply_to_me"].(map[string]interface{}); ok {
		replyId := replyToMe["id"].(float64)
		log.Printf("Replying to topology request %d", replyId)
	}
}

func handleTopology(msg map[string]interface{}) {
	body := msg["body"].(map[string]interface{})
	topologyMap := make(map[string][]string)

	if topo, ok := body["topology"].(map[string]interface{}); ok {
		for k, v := range topo {
			vArr := v.([]interface{})
			var strs []string
			for _, x := range vArr {
				strs = append(strs, x.(string))
			}
			topologyMap[k] = strs
		}
	}

	log.Printf("Node received topology: %+v", topologyMap)

	replyId := msg["msg_id"].(float64)
	// Send reply

	msgOut, _ := json.Marshal(map[string]interface{}{
		"type":       "topology_ok",
		"in_reply_to": replyId,
	})
	os.WriteFile("/dev/stdout", msgOut, 0)
}

func handleBroadcast(msg map[string]interface{}) {
	body := msg["body"].(map[string]interface{})
	value := body["value"].(float64)
	msgID := int(body["msg_id"].(float64))

	log.Printf("Node receiving broadcast value %d with id %d", value, msgID)

	// Store locally
	key := broadcastKey(msgID)
	localStore[key] = value

	// Forward to neighbors if we have them
	if topoCh, ok := getTopologyCh(msg["id"].(string)); ok {
		msgOut, _ := json.Marshal(map[string]interface{}{
			"type":       "broadcast",
			"value":      value,
			"msg_id":     msgID,
			"sender_id":  msg["id"],
		})

		for _, neighbor := range topoCh {
			os.WriteFile("/dev/stdout", append(msgOut, '\n'), 0)
		}
	}

	replyId := msg["msg_id"].(float64)
	msgOut, _ := json.Marshal(map[string]interface{}{
		"type":       "broadcast_ok",
		"in_reply_to": replyId,
	})
	os.WriteFile("/dev/stdout", append(msgOut, '\n'), 0)
}

func handleRead(msg map[string]interface{}) {
	replyId := int(msg["msg_id"].(float64))

	value := localStore[broadcastKey(replyId)]
	if value != nil {
		msgOut, _ := json.Marshal(map[string]interface{}{
			"type":      "read_ok",
			"in_reply_to": float64(replyId),
			"messages":  []float64{value},
		})
		os.WriteFile("/dev/stdout", append(msgOut, '\n'), 0)
	} else {
		msgOut, _ := json.Marshal(map[string]interface{}{
			"type":      "read_ok",
			"in_reply_to": float64(replyId),
			"messages":  []float64{},
		})
		os.WriteFile("/dev/stdout", append(msgOut, '\n'), 0)
	}
}

func handleReplyToMe(msg map[string]interface{}) {
	body := msg["body"].(map[string]interface{})
	typeName := body["type"].(string)
	value := float64(body["value"].(float64))
	msgID := int(body["msg_id"].(float64))

	key := broadcastKey(msgID)
	localStore[key] = value

	log.Printf("Node stored forwarded value %d with key %s", value, key)
}

var localStore = make(map[int]float64)
var topologyChs = make(map[string]chan string)

func getTopologyCh(nodeId string) (chan string, bool) {
	if _, ok := topologyChs[nodeId]; !ok {
		ch := make(chan string, 256)
		topologyChs[nodeId] = ch
		return ch, true
	}
	return topologyChs[nodeId], true
}

